# Inside an Executa plugin (executa_sdk).
from executa_sdk import ImageClient, ImageError, IMAGE_ERR_NOT_GRANTED, IMAGE_ERR_QUOTA_EXCEEDED

image = ImageClient()                       # uses default stdout write_frame

async def make_poster(req_id: str, invoke_id: str, prompt: str) -> dict:
    try:
        result = await image.generate(
            prompt=prompt,
            n=2,
            size="1024x1024",
            metadata={"executa_invoke_id": invoke_id},  # billing correlation — always include
            timeout=120.0,
        )
    except ImageError as e:
        if e.code == IMAGE_ERR_NOT_GRANTED:
            return {"success": False, "error": "user has not granted image generation"}
        if e.code == IMAGE_ERR_QUOTA_EXCEEDED:
            return {"success": False, "error": "image quota exhausted; ask the user to upgrade"}
        raise

    # Each url is a transient host-stored HTTPS URL (~30 min TTL).
    # Persist via `host/uploadFile` if you need it long-term.
    urls = [img["url"] for img in result["images"]]
    return {"success": True, "data": {"images": urls, "model": result["model"]}}

# Restyle a previously-generated image in cyberpunk neon.
from executa_sdk import ImageClient, ImageError, IMAGE_ERR_EDIT_NOT_SUPPORTED, IMAGE_ERR_MASK_UNSUPPORTED

image = ImageClient()

async def restyle(invoke_id: str, source_url: str) -> dict:
    try:
        result = await image.edit(
            image_url=source_url,
            prompt="Restyle in cyberpunk neon. Preserve composition.",
            n=1,
            metadata={"executa_invoke_id": invoke_id},
        )
    except ImageError as e:
        if e.code == IMAGE_ERR_EDIT_NOT_SUPPORTED:
            # User's provider can't edit — fall back to a fresh generate.
            return await image.generate(prompt="Cyberpunk neon poster", n=1,
                                       metadata={"executa_invoke_id": invoke_id})
        if e.code == IMAGE_ERR_MASK_UNSUPPORTED:
            raise   # caller passed a mask the provider can't honour
        raise
    return {"images": [img["url"] for img in result["images"]], "model": result["model"]}
